// Generated by agent-workflows deploy.py: routes heavy bash commands (tests,
// builds, type-checks) through the machine-wide queue so parallel agents don't
// freeze the machine. Classification lives in heavy.py (`wrap`), shared with
// the Claude Code hook, so both harnesses queue exactly the same commands.
import { spawnSync } from "node:child_process"

const PYTHON = __PYTHON__
const HEAVY = __HEAVY__
// Waiting for a slot counts against the tool timeout; heavy.py gives up first (exit 75).
const MIN_TIMEOUT_MS = 600000

export const AgentWorkflowsHeavyQueue = async () => ({
  "tool.execute.before": async (input, output) => {
    if (input.tool !== "bash" || typeof output.args?.command !== "string") return
    const res = spawnSync(PYTHON, [HEAVY, "wrap", "bash"], {
      input: output.args.command,
      encoding: "utf8",
    })
    if (res.status !== 0 || !res.stdout) return
    output.args.command = res.stdout
    output.args.timeout = Math.max(output.args.timeout ?? 0, MIN_TIMEOUT_MS)
  },
})
